// PUBLIC FUNDING — and the one number that decides whether to write the bid or take the contract.
//
// Grants and government contracts are the least-competed money available to a small technical
// operator, and the reason is unglamorous: the paperwork deters people. A solicitation with four
// bidders and one with four hundred pay the same, and which one you are looking at is knowable
// before you spend a week on it.
//
// THE BID IS PRICED AGAINST THE HOUR IT COSTS. An award is not revenue, it is a lottery ticket with
// a known price: the hours to write it. So every opportunity here is reduced to ONE comparable
// figure — expected value per hour of bid effort — and that figure is compared against the hourly a
// contract would pay for the same hours. A $150,000 grant at a 10% hit rate costing 80 hours is
// $187/hour of expectation; the same 80 hours contracting at $120 is $9,600 CERTAIN. Which is better
// depends on the runway, and that is a computation rather than an opinion.
//
// THREE REFUSALS, because each is a way to waste a week:
//
//  1. NOT ELIGIBLE IS NOT RANKED. An opportunity you cannot legally win has no expected value, and
//     leaving it in the list to be sorted by size puts the biggest unwinnable thing at the top.
//  2. AN UNKNOWN HIT RATE IS NOT A GUESS. Where no evidence supports a probability, the expected
//     value is UNDEFINED and the row says so. A default of 10% would be a number somebody acts on.
//  3. A DEADLINE YOU CANNOT MAKE IS A REFUSAL, not a discount. Bidding late is bidding zero, and a
//     solicitation needing 80 hours in the next 5 days is not a 60%-confidence opportunity, it is a
//     no with extra steps.
import { type Money, money, scale } from "@/features/finance/lib/money";

/** Where an opportunity came from. All PUBLIC — no credentials, no scraping, no ToS exposure. */
export interface FundingSource {
  readonly id: string;
  readonly name: string;
  /** What it actually lists, in words, so the roster is readable without opening anything. */
  readonly carries: string;
  /** The documented public API base. UNVERIFIED until somebody has called it — see `verified`. */
  readonly api?: string;
  /** FALSE until a real call has been made and the response shape checked. */
  readonly verified: boolean;
  readonly caveat?: string;
}

export type Vehicle =
  /** Non-dilutive research funding — the highest award-to-competition ratio available here. */
  | "sbir"
  /** A grant: awarded, not bought. Usually the longest cycle. */
  | "grant"
  /** A contract for work, competed. */
  | "contract"
  /** A pre-competed vehicle you can be added to. */
  | "idiq"
  /** A state or local request for proposal — thinner competition than federal, faster cycles. */
  | "rfp";

export interface Opportunity {
  readonly id: string;
  readonly title: string;
  readonly sourceId: string;
  readonly vehicle: Vehicle;
  /** The ceiling, where one is published. Absent means unstated — not zero. */
  readonly award?: Money;
  /** `YYYY-MM-DD`. */
  readonly closes: string;
  /** Hours to produce a credible submission. The real price of the ticket. */
  readonly bidHours: number;
  /** 0-1. UNDEFINED unless something actually supports it — a default here is a lie with a number. */
  readonly hitRate?: number;
  /** Requirements that must ALL hold, as plain assertions about you. */
  readonly requires: readonly string[];
}

/** What is true about the bidder, checked against an opportunity's `requires`. */
export type Capabilities = Readonly<Record<string, boolean>>;

export type Verdict = "biddable" | "ineligible" | "too-late" | "unpriceable";

export interface Assessment {
  readonly opportunity: Opportunity;
  readonly verdict: Verdict;
  /** award × hitRate. Undefined when either is. */
  readonly expected?: Money;
  /** The comparable number: expected value per hour of bid effort. */
  readonly perHour?: Money;
  /** What contracting those same hours would pay, for the comparison that decides it. */
  readonly contractingAlternative: Money;
  /** True when the bid beats simply billing the hours. */
  readonly beatsContracting: boolean;
  readonly hoursAvailable: number;
  /** Why it is not biddable, when it is not. */
  readonly why?: string;
  readonly unmet: readonly string[];
}

export interface AssessOptions {
  /** `YYYY-MM-DD`. Passed in, never read from a clock. */
  readonly asOf: string;
  /** What the bidder can truthfully assert. */
  readonly capabilities: Capabilities;
  /** Billable hourly the same effort could earn instead — the opportunity cost, and the whole
   *  comparison. Comes from `income-engine`'s rate floor. */
  readonly contractingRate: Money;
  /** Hours per week available for bid writing. */
  readonly hoursPerWeek?: number;
}

const daysBetween = (a: string, b: string): number =>
  Math.round((Date.parse(`${b}T00:00:00Z`) - Date.parse(`${a}T00:00:00Z`)) / 86_400_000);

/**
 * The public sources. EVERY ONE IS UNVERIFIED — the endpoints are recorded from documentation, not
 * from a call — and `verified` says so on each, the same discipline the institution profiles use.
 * A scanner that reported nothing because a URL moved would look identical to a quiet week.
 */
export const FUNDING_SOURCES: readonly FundingSource[] = [
  {
    id: "sbir",
    name: "SBIR / STTR",
    carries: "federal research solicitations across ~11 agencies; non-dilutive, Phase I typically the entry point",
    api: "https://api.www.sbir.gov/public/api/",
    verified: false,
    caveat: "the highest award-to-competition ratio on this list, and the one whose eligibility rules are strictest — check ownership and size standards FIRST, not last",
  },
  {
    id: "grants-gov",
    name: "Grants.gov",
    carries: "every federal grant opportunity, all agencies",
    api: "https://api.grants.gov/v1/api/",
    verified: false,
    caveat: "volume is enormous and most of it is irrelevant — the eligibility gate is doing the real work here, not the search",
  },
  {
    id: "sam-gov",
    name: "SAM.gov",
    carries: "federal contract opportunities, notices and awards; registration is required to BID but not to search",
    api: "https://api.sam.gov/opportunities/v2/",
    verified: false,
    caveat: "requires a free API key for programmatic access, and registration (UEI) before any bid can be submitted — start that early, it is slow",
  },
  {
    id: "state-local",
    name: "State and local procurement",
    carries: "state, county and municipal RFPs — no single index, one portal per jurisdiction",
    verified: false,
    caveat: "thinner competition and faster cycles than federal, but there is no unified API; this is per-portal and partly manual",
  },
];

export const sourceFor = (id: string): FundingSource | undefined => FUNDING_SOURCES.find((s) => s.id === id);

/** Requirements the bidder cannot truthfully assert. */
export function unmetRequirements(o: Opportunity, capabilities: Capabilities): string[] {
  return o.requires.filter((r) => capabilities[r] !== true);
}

/**
 * Price one opportunity, and refuse rather than discount.
 *
 * The order is the point: eligibility, then the deadline, then the arithmetic. Something you cannot
 * win or cannot submit has no expected value at all, and computing one for it would put an
 * impossible row at the top of a list sorted by size.
 */
export function assess(o: Opportunity, opts: AssessOptions): Assessment {
  const { asOf, capabilities, contractingRate, hoursPerWeek = 20 } = opts;
  const contractingAlternative = scale(contractingRate, o.bidHours);
  const daysLeft = daysBetween(asOf, o.closes);
  const hoursAvailable = Math.max(0, (daysLeft / 7) * hoursPerWeek);

  const base = { opportunity: o, contractingAlternative, hoursAvailable, beatsContracting: false };

  const unmet = unmetRequirements(o, capabilities);
  if (unmet.length) {
    return {
      ...base,
      verdict: "ineligible",
      why: `cannot truthfully assert: ${unmet.join(", ")} — an opportunity you cannot legally win has no expected value, so it is not ranked at all`,
      unmet,
    };
  }

  if (daysLeft < 0) {
    return { ...base, verdict: "too-late", why: `closed ${-daysLeft} day(s) ago`, unmet: [] };
  }
  if (hoursAvailable < o.bidHours) {
    // A deadline you cannot make is a refusal, not a discount. Bidding late is bidding zero.
    return {
      ...base,
      verdict: "too-late",
      why: `needs ${o.bidHours}h and there are ${Math.floor(hoursAvailable)}h before it closes — bidding late is bidding zero, so this is a no rather than a lower-confidence yes`,
      unmet: [],
    };
  }

  if (o.award === undefined || o.hitRate === undefined) {
    // UNKNOWN IS NOT A GUESS. A default hit rate is a number somebody would act on.
    return {
      ...base,
      verdict: "unpriceable",
      why: o.award === undefined
        ? "no award ceiling is published, so there is nothing to multiply — find the number before spending the hours"
        : "nothing supports a hit rate for this, and a default would be a fabricated number somebody acts on",
      unmet: [],
    };
  }

  const expectedMinor = Math.round(o.award.minor * o.hitRate);
  const perHourMinor = o.bidHours > 0 ? Math.round(expectedMinor / o.bidHours) : expectedMinor;
  return {
    ...base,
    verdict: "biddable",
    expected: money(expectedMinor, o.award.currency),
    perHour: money(perHourMinor, o.award.currency),
    beatsContracting: perHourMinor > contractingRate.minor,
    unmet: [],
  };
}

/**
 * Everything, best first — and the unbiddable KEPT, at the bottom, with the reason.
 *
 * Dropping them would make the list shorter and the same opportunity would be re-found, re-assessed
 * and re-rejected next week. The reason is the durable part.
 */
export function rank(opportunities: readonly Opportunity[], opts: AssessOptions): Assessment[] {
  const order: Record<Verdict, number> = { biddable: 0, unpriceable: 1, ineligible: 2, "too-late": 3 };
  return opportunities
    .map((o) => assess(o, opts))
    .sort(
      (a, b) =>
        order[a.verdict] - order[b.verdict] ||
        (b.perHour?.minor ?? -1) - (a.perHour?.minor ?? -1) ||
        a.opportunity.closes.localeCompare(b.opportunity.closes),
    );
}

/** The ones worth the hours: biddable AND better than simply billing the same time. */
export const worthTheHours = (assessments: readonly Assessment[]): Assessment[] =>
  assessments.filter((a) => a.verdict === "biddable" && a.beatsContracting);

/** Total bid hours a plan commits to — the constraint people forget until they are inside it. */
export const totalBidHours = (assessments: readonly Assessment[]): number =>
  assessments.reduce((n, a) => n + a.opportunity.bidHours, 0);

/**
 * A capability nobody has asserted is the thing to go and fix.
 *
 * Across everything ineligible, which requirement blocks the most? That is a work item — a
 * registration, a certification, a past-performance record — and it is usually cheaper than any
 * single bid it unblocks.
 */
export function blockingRequirements(assessments: readonly Assessment[]): { requirement: string; blocks: number }[] {
  const counts = new Map<string, number>();
  for (const a of assessments) {
    for (const r of a.unmet) counts.set(r, (counts.get(r) ?? 0) + 1);
  }
  return [...counts.entries()]
    .map(([requirement, blocks]) => ({ requirement, blocks }))
    .sort((x, y) => y.blocks - x.blocks || x.requirement.localeCompare(y.requirement));
}

/** One line a person can act on. */
export function summarise(a: Assessment): string {
  const t = a.opportunity.title;
  if (a.verdict !== "biddable") return `${t} — ${a.verdict.toUpperCase()}: ${a.why}`;
  const verdict = a.beatsContracting
    ? `beats billing the same ${a.opportunity.bidHours}h`
    : `does NOT beat billing the same ${a.opportunity.bidHours}h (${a.contractingAlternative.minor} certain)`;
  return `${t} — ${a.perHour!.minor}/h of expectation, ${verdict}`;
}

