import { describe, it, expect } from "vitest";
import { fromMajor, type Money } from "@/features/finance/lib/money";
import {
  type Opportunity,
  FUNDING_SOURCES,
  assess,
  blockingRequirements,
  rank,
  sourceFor,
  summarise,
  totalBidHours,
  unmetRequirements,
  worthTheHours,
} from "@/features/finance/lib/opportunity";

// SYNTHETIC FIXTURES ONLY. No real solicitation, award or registration belongs in this repo.
const usd = (major: number): Money => fromMajor(major, "USD");

const opp = (over: Partial<Opportunity> = {}): Opportunity => ({
  id: "o1",
  title: "Example Phase I",
  sourceId: "sbir",
  vehicle: "sbir",
  award: usd(150_000),
  closes: "2026-09-01",
  bidHours: 80,
  hitRate: 0.1,
  requires: [],
  ...over,
});

const opts = (over: Partial<Parameters<typeof assess>[1]> = {}) => ({
  asOf: "2026-07-01",
  capabilities: {},
  contractingRate: usd(120),
  hoursPerWeek: 20,
  ...over,
});

describe("THE BID IS PRICED AGAINST THE HOUR IT COSTS", () => {
  it("reduces an award to expected value per hour of bid effort", () => {
    // $150,000 at a 10% hit rate over 80 hours is $187.50/hour of expectation. That is the only
    // figure that compares across a grant, a contract and simply billing the time.
    const a = assess(opp(), opts());
    expect(a.verdict).toBe("biddable");
    expect(a.expected!.minor).toBe(usd(15_000).minor);
    expect(a.perHour!.minor).toBe(usd(187.5).minor);
  });

  it("compares it against billing the SAME hours, which is the decision", () => {
    const a = assess(opp(), opts());
    // 80h at $120 is $9,600 CERTAIN against $15,000 of expectation.
    expect(a.contractingAlternative.minor).toBe(usd(9_600).minor);
    expect(a.beatsContracting).toBe(true);

    // Raise the contracting rate past the expectation and the answer flips — nothing about the
    // opportunity changed, only what else those hours could do.
    const rich = assess(opp(), opts({ contractingRate: usd(250) }));
    expect(rich.beatsContracting).toBe(false);
    expect(summarise(rich)).toContain("does NOT beat billing");
  });

  it("a small award with a high hit rate can beat a large one with a low one", () => {
    // $1m at 1% over 100h is $100/h. $40k at 50% over 20h is $1,000/h. The headline number is the
    // one people chase and it is the wrong one.
    const lottery = assess(opp({ id: "big", award: usd(1_000_000), hitRate: 0.01, bidHours: 100 }), opts());
    const modest = assess(opp({ id: "small", award: usd(40_000), hitRate: 0.5, bidHours: 20 }), opts());
    expect(lottery.verdict).toBe("biddable");
    expect(modest.perHour!.minor).toBeGreaterThan(lottery.perHour!.minor);
    expect(modest.opportunity.award!.minor).toBeLessThan(lottery.opportunity.award!.minor);
  });

  it("a bid too big for the time left is refused however good the arithmetic looks", () => {
    // 200h against 62 days at 20h/week is 177h available. The expectation is irrelevant if the
    // submission cannot be written.
    const a = assess(opp({ award: usd(1_000_000), hitRate: 0.01, bidHours: 200 }), opts());
    expect(a.verdict).toBe("too-late");
    expect(a.expected).toBeUndefined();
  });

  it("does not divide by zero on an opportunity with no bid cost", () => {
    const a = assess(opp({ bidHours: 0 }), opts());
    expect(a.perHour!.minor).toBe(a.expected!.minor);
  });
});

describe("three refusals, each a way to waste a week", () => {
  it("does NOT rank something it cannot legally win", () => {
    // Leaving it in to be sorted by size puts the biggest unwinnable thing at the top.
    const a = assess(opp({ requires: ["sam-registered", "us-owned"] }), opts({ capabilities: { "us-owned": true } }));
    expect(a.verdict).toBe("ineligible");
    expect(a.unmet).toEqual(["sam-registered"]);
    expect(a.expected).toBeUndefined();
    expect(a.perHour).toBeUndefined();
    expect(a.why).toContain("no expected value");
  });

  it("treats an unmeetable deadline as a NO, not a discount", () => {
    // 80h needed, 5 days left at 20h/week is 14h. Bidding late is bidding zero.
    const a = assess(opp({ closes: "2026-07-06" }), opts());
    expect(a.verdict).toBe("too-late");
    expect(a.why).toContain("bidding late is bidding zero");
    expect(a.expected).toBeUndefined();
  });

  it("says a closed solicitation is closed", () => {
    const a = assess(opp({ closes: "2026-06-01" }), opts());
    expect(a.verdict).toBe("too-late");
    expect(a.why).toContain("closed 30 day(s) ago");
  });

  it("refuses to invent a hit rate, because a default is a number somebody acts on", () => {
    const a = assess(opp({ hitRate: undefined }), opts());
    expect(a.verdict).toBe("unpriceable");
    expect(a.expected).toBeUndefined();
    expect(a.why).toContain("fabricated number");
  });

  it("refuses to price an award nobody published", () => {
    const a = assess(opp({ award: undefined }), opts());
    expect(a.verdict).toBe("unpriceable");
    expect(a.why).toContain("nothing to multiply");
  });

  it("checks eligibility BEFORE the deadline, so an impossible bid reads as impossible", () => {
    // Both wrong. The one that cannot be fixed by hurrying is the one to report.
    const a = assess(opp({ closes: "2026-07-02", requires: ["cage-code"] }), opts());
    expect(a.verdict).toBe("ineligible");
  });
});

describe("rank — the unbiddable are kept, at the bottom, with the reason", () => {
  const all = [
    opp({ id: "good", title: "Good", award: usd(150_000), hitRate: 0.2, bidHours: 40 }),
    opp({ id: "meh", title: "Meh", award: usd(60_000), hitRate: 0.1, bidHours: 60 }),
    opp({ id: "blocked", title: "Blocked", requires: ["cage-code"] }),
    opp({ id: "gone", title: "Gone", closes: "2026-01-01" }),
    opp({ id: "vague", title: "Vague", hitRate: undefined }),
  ];

  it("puts biddable first, ordered by expectation per hour", () => {
    const out = rank(all, opts());
    expect(out.slice(0, 2).map((a) => a.opportunity.id)).toEqual(["good", "meh"]);
    expect(out[0].perHour!.minor).toBeGreaterThan(out[1].perHour!.minor);
  });

  it("keeps everything, because a dropped row is re-found and re-rejected next week", () => {
    const out = rank(all, opts());
    expect(out).toHaveLength(5);
    expect(out.map((a) => a.verdict).slice(2)).toEqual(["unpriceable", "ineligible", "too-late"]);
  });

  it("worthTheHours is narrower than biddable — it also has to beat billing", () => {
    const out = rank(all, opts({ contractingRate: usd(200) }));
    expect(out.filter((a) => a.verdict === "biddable")).toHaveLength(2);
    // Meh is $100/h of expectation against a $200 rate; only Good survives.
    expect(worthTheHours(out).map((a) => a.opportunity.id)).toEqual(["good"]);
  });

  it("adds up what a plan actually commits to in hours", () => {
    // Only Good clears the $120 rate — Meh is $100/h of expectation — so the committed hours are
    // Good's 40, not the 100 both would cost.
    expect(totalBidHours(worthTheHours(rank(all, opts())))).toBe(40);
    expect(totalBidHours(rank(all, opts()).filter((a) => a.verdict === "biddable"))).toBe(100);
  });
});

describe("blockingRequirements — the cheapest thing to go and fix", () => {
  it("names the requirement that blocks the most, most-blocking first", () => {
    // A registration that unblocks four bids is almost always cheaper than any one of them.
    const out = rank(
      [
        opp({ id: "a", requires: ["sam-registered"] }),
        opp({ id: "b", requires: ["sam-registered"] }),
        opp({ id: "c", requires: ["sam-registered", "cage-code"] }),
        opp({ id: "d", requires: ["cage-code"] }),
      ],
      opts(),
    );
    expect(blockingRequirements(out)).toEqual([
      { requirement: "sam-registered", blocks: 3 },
      { requirement: "cage-code", blocks: 2 },
    ]);
  });

  it("is empty when nothing is blocked", () => {
    expect(blockingRequirements(rank([opp()], opts()))).toEqual([]);
  });

  it("counts only what is actually unmet", () => {
    const o = opp({ requires: ["a", "b"] });
    expect(unmetRequirements(o, { a: true })).toEqual(["b"]);
    expect(unmetRequirements(o, { a: true, b: true })).toEqual([]);
    // A capability set to false is as unmet as one that is absent.
    expect(unmetRequirements(o, { a: true, b: false })).toEqual(["b"]);
  });
});

describe("the sources are public, and honestly unverified", () => {
  it("says every source is UNVERIFIED and names what to check", () => {
    expect(FUNDING_SOURCES.every((s) => s.verified === false)).toBe(true);
    expect(FUNDING_SOURCES.every((s) => (s.caveat ?? "").length > 0)).toBe(true);
    expect(FUNDING_SOURCES.every((s) => s.carries.length > 0)).toBe(true);
  });

  it("covers federal research, federal grants, federal contracts and state/local", () => {
    expect(FUNDING_SOURCES.map((s) => s.id)).toEqual(["sbir", "grants-gov", "sam-gov", "state-local"]);
    expect(sourceFor("sbir")!.name).toContain("SBIR");
    expect(sourceFor("nowhere")).toBeUndefined();
  });

  it("does not claim an API for the one that has none", () => {
    // State and local procurement has no unified index. Inventing an endpoint for it would produce a
    // scanner that silently returned nothing and looked like a quiet week.
    expect(sourceFor("state-local")!.api).toBeUndefined();
    expect(sourceFor("state-local")!.caveat).toContain("no unified API");
  });
});
